"""Convert seconds to a formatted string

    Convert seconds: 3661
    To formatted: "   1:01:01"
    """
def format_seconds(seconds: Any) -> object {
    hour_factor = 1;
    if (seconds < 0) {
        hour_factor = -1;
        seconds = -seconds;
    }
    hours = seconds // 3600;
    minutes = (seconds % 3600) // 60;
    seconds = seconds % 60;
    return "{:4d}:{:02d}:{:02d}".format((hour_factor * hours), minutes, seconds);
}

"""
    bio2ot function for absa task
    """
def bio2ot_absa(absa_tag_sequence: Any) -> object {
    new_absa_sequence = [];
    n_tags = len(absa_tag_sequence);
    for i in range(n_tags) {
        absa_tag = absa_tag_sequence[i];
        if ((absa_tag == 'O') or (absa_tag == 'EQ')) {
            new_absa_sequence.append('O');
        } else {
            (pos, sentiment) = absa_tag.split('-');
            new_absa_sequence.append(('T-%s' % sentiment));
        }
    }
    return new_absa_sequence;
}

